        pegs = state[3]
        if len(pegs) < 2:
            separation = 0
        else:
            separation = min(
                abs(a[0] - b[0]) + abs(a[1] - b[1])
                for index, a in enumerate(pegs)
                for b in pegs[index + 1:]
