            generated += 1
            child_state = board(child.frame())
            if child_state == state or child_state in seen:
                continue
            seen.add(child_state)
            child_path = path + (action,)
            serial += 1
            heappush(queue, (
                priority(child_state, child_path), serial, child, child_path,
            ))

        slots, carriers, bridges, pegs = state
        destinations = set(slots) | set(carriers)
        for kind, source in (
            *(("peg", piece) for piece in pegs),
            *(("bridge", piece) for piece in bridges),
        ):
