                child = node.clone()
                play_lattice_moves(child, ((source, destination),))
                generated += 1
                child_state = board(child.frame())
                child_pieces = child_state[3 if kind == "peg" else 2]
                if (
                    child.levels_completed <= 6
                    and (source in child_pieces or destination not in child_pieces)
                ):
                    continue
                if child_state in seen:
                    continue
                seen.add(child_state)
                child_path = path + ((source, destination),)
                serial += 1
                heappush(queue, (
                    priority(child_state, child_path), serial, child, child_path,
                ))

        if len(seen) % 50 == 0:
            print("SEARCH", len(seen), generated, priority(state, path))
